#!/usr/bin/env bash
# Prints a throwaway .env with fresh random secrets, for CI and first runs (PLAN 16.2, M4b).
# Usage: scripts/make-env.sh > .env
# Nothing it prints is reused anywhere: every run makes new values. Never use it for a real deployment.
set -euo pipefail

rand() { openssl rand -hex 24; }

key_file=$(mktemp)
trap 'rm -f "$key_file"' EXIT
openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:2048 -out "$key_file" 2>/dev/null
signing_key=$(openssl pkcs8 -topk8 -nocrypt -in "$key_file" -outform DER | base64 | tr -d '\n')

cat <<EOF
# Generated by scripts/make-env.sh for a throwaway stack. Do not reuse these values.
POSTGRES_PASSWORD=$(rand)
S3_ACCESS_KEY=$(rand)
S3_SECRET_KEY=$(rand)
GATEWAY_HOST_PORT=8080
AUTH_JWT_PRIVATE_KEY_BASE64=${signing_key}
AUTH_SEED_PLATFORM_ADMIN_EMAIL=smoke.platform.admin@example.com
AUTH_SEED_PLATFORM_ADMIN_PASSWORD=$(rand)
REDIS_PASSWORD=$(rand)
POLICY_FIELD_KEY_BASE64=$(openssl rand -base64 32)
POLICY_FIELD_KEY_ID=policy-key-1
SERVICE_SECRET_POLICY_SERVICE=$(rand)
EOF
